from dataclasses import dataclass
@dataclass(frozen=True)
class MonsterType:
    id: str
    base_health: int
    attack: str
    def new_monster(self) -> "Monster": return Monster(self)

class Monster:
    def __init__(self, breed: MonsterType):
        self.breed = breed
        self.health = breed.base_health

def build_type(spec: dict) -> type:
    def attack(self, _text=spec["attack"]):
        return _text
    def __init__(self):
        self.health = spec["base_health"]
    return type(spec["id"], (object,), {
        "attack": attack, "__init__": __init__,
        "base_health": spec["base_health"],
    })

